(()=>{'use strict';const dict={"Una mesa para ti":"A table for you","Ver la carta":"View menu","Nuestra mesa":"Our table","La carta":"The menu","La Corte en vivo":"La Corte live","Encuéntranos":"Find us","Descubrir la carta":"Discover the menu","UNA MESA. MIL GANAS DE VOLVER.":"ONE TABLE. A THOUSAND REASONS TO RETURN.","Italia,":"Italy,","a la mesa.":"at your table.","LA DOLCE VITA, AQUÍ MISMO.":"LA DOLCE VITA, RIGHT HERE.","Pasta, pizza.":"Pasta, pizza.","De la carbonara a tu pizza favorita.":"From carbonara to your favourite pizza.","Descubre nuestras pastas, las pizzas de la casa y los sabores de nuestra carta, junto al paseo marítimo de Fuengirola.":"Discover our pasta, house pizzas and menu by the Fuengirola seafront.","Elige tu plato":"Choose your dish","A LA MESA":"AT THE TABLE","Nuestra":"Our","cocina.":"kitchen.","Todos nuestros sabores":"Explore our menu","SIN FILTROS. CON MUCHO SABOR.":"UNFILTERED. FULL OF FLAVOUR.","en vivo.":"live.","Lo que sale de la cocina.":"Fresh from the kitchen.","Lo que pasa en la mesa.":"Moments at the table.","Desliza y quédate un momento.":"Swipe and stay a while.","Vienen por la pasta.":"They come for the pasta.","Vuelven por todo.":"They return for everything.","1.048 valoraciones en Google":"1,048 reviews on Google","Nos vemos":"See you","Pizza, pasta y una mesa junto al mar.":"Pizza, pasta and a table by the sea.","El resto, lo ponemos nosotros.":"We take care of the rest.","TU PRÓXIMA MESA":"YOUR NEXT TABLE","¿Comemos?":"Shall we eat?","Reserva directamente con nuestro equipo.":"Book directly with our team.","Reservar mesa":"Book a table","Dónde estamos":"Find us","Abrir en Google Maps":"Open in Google Maps","Horario":"Opening hours","Lunes, martes y jueves a domingo":"Monday, Tuesday and Thursday to Sunday","Miércoles cerrado":"Closed on Wednesdays","Lunes y martes":"Monday and Tuesday","Miércoles":"Wednesday","Cerrado":"Closed","Jueves a domingo":"Thursday to Sunday","Horario publicado":"Published opening hours","Visítanos":"Visit us","Cómo llegar":"Get directions","Reservas · +34 655 868 593":"Bookings · +34 655 868 593","Nuestra cocina":"Our kitchen","Carta completa":"Full menu","Carta original":"Original menu","Imágenes y fuentes":"Images and sources","Volver arriba":"Back to top","Nos vemos en Instagram":"Find us on Instagram","UN SITIO PARA TI":"A PLACE FOR YOU","Llama al equipo para consultar disponibilidad y reservar tu mesa.":"Call our team to check availability and book your table.","La reserva se confirma directamente con el restaurante.":"Bookings are confirmed directly with the restaurant.","Imágenes":"Images","y fuentes.":"and sources.","Inicio":"Home","Reservar":"Book a table","La carta de La Corte Italiana.":"The menu at La Corte Italiana.","CATEGORÍA":"CATEGORY","Todos los platos":"All dishes","Tapas":"Tapas","Ensaladas":"Salads","Pasta fresca":"Fresh pasta","Lasaña":"Lasagne","Carnes":"Meat","Pescados":"Fish","Postres":"Desserts","No encontramos ese plato. Prueba con otro nombre.":"No dishes found. Try a different name.","Tapas, ensaladas, pastas, pizzas, carnes y pescados de nuestra carta.":"Tapas, salads, pasta, pizza, meat and fish from our menu.","Consulta con el restaurante los precios, ingredientes, alérgenos y disponibilidad actuales. Los platos son recreaciones con IA sobre fotografías del local real.":"Ask the restaurant about current prices, ingredients, allergens and availability. Food images are AI recreations based on photographs of the actual restaurant.","Ver la carta original del restaurante":"View the original restaurant menu","Consultar disponibilidad · +34 655 868 593":"Check availability · +34 655 868 593","Volver a La Corte Italiana":"Back to La Corte Italiana","Consultar con el restaurante":"Ask the restaurant","Plato de la carta de La Corte Italiana. Consulta los ingredientes, alérgenos y disponibilidad con el equipo.":"A dish from the La Corte Italiana menu. Ask our team about ingredients, allergens and availability.","Ver original en Instagram":"View original on Instagram","Ver este reel en Instagram":"View this reel on Instagram","Reproducir desde el inicio":"Play from the beginning","Abrir los reels en Instagram":"Open reels on Instagram","Saltar al contenido":"Skip to content","Buscar un plato":"Search for a dish","Abrir menú":"Open menu","Cerrar menú":"Close menu","Plato anterior":"Previous dish","Plato siguiente":"Next dish","Reels anteriores":"Previous reels","Reels siguientes":"Next reels","Reseña anterior":"Previous review","Reseña siguiente":"Next review","Cerrar plato":"Close dish","Cerrar reservas":"Close booking","Cerrar información":"Close information","Las fotografías del local son originales del restaurante. Las imágenes de los platos son recreaciones con IA a partir de fotografías reales de distintas mesas y zonas del restaurante. El logotipo y los veinte reels proceden del perfil de La Corte Italiana en Instagram.":"The venue photographs are original restaurant photographs. Dish images are AI recreations based on real photographs of different restaurant tables and areas. The logo and twenty reels come from La Corte Italiana’s Instagram profile.","Dirección, teléfono, valoración y extractos de reseñas: Google Maps, consultado el 10 de noviembre de 2026. La carta se ha transcrito de las fotografías con el logo de La Corte Italiana. Consulta precios y disponibilidad con el equipo.":"Address, phone, rating and review excerpts: Google Maps, accessed 10 November 2026. The menu was transcribed from photographs bearing the La Corte Italiana logo. Ask the team about prices and availability."}, originals=new WeakMap(),attributes=new WeakMap();let language='es';try{language=localStorage.getItem('corte-language')==='en'?'en':'es'}catch{}const header=document.querySelector('.header');function scrollHeader(){if(!header)return;const scrolled=window.scrollY>(header.classList.contains('is-scrolled')?40:80);header.classList.toggle('is-scrolled',scrolled);const lower=header.querySelector('.header-lower');if(lower){lower.inert=!scrolled;lower.setAttribute('aria-hidden',String(!scrolled))}}window.addEventListener('scroll',scrollHeader,{passive:true});scrollHeader();
Object.assign(dict,{"DE ITALIA. DE FAMILIA.":"FROM ITALY. FROM FAMILY.","Italianos de verdad.":"Truly Italian.","Y se nota en la mesa.":"You can taste it at the table.","Detrás de La Corte hay una familia italiana que vive la cocina con pasión. De esas que te reciben con cercanía y ponen el corazón en cada plato.":"Behind La Corte is an Italian family with a passion for cooking. A family that welcomes you warmly and puts its heart into every dish.","Cocinamos con productos italianos y con ese cariño por lo nuestro que no se puede fingir. Nos gusta comer bien, compartir lo que sabemos y llevar a tu mesa los sabores con los que hemos crecido.":"We cook with Italian ingredients and a love for our roots that comes naturally. We love good food, sharing what we know and bringing the flavours we grew up with to your table.","La pasta, la pizza, el último bocado de postre… Para nosotros, todo cuenta. Porque una buena comida no solo se prepara: se disfruta juntos.":"The pasta, the pizza, the last bite of dessert… Every detail matters to us. Because a good meal is made to be enjoyed together.","La familia de La Corte":"The La Corte family","ITALIA EN LA COCINA. FAMILIA EN LA MESA.":"ITALY IN THE KITCHEN. FAMILY AT THE TABLE."});function english(text){if(dict[text])return dict[text];const status=text.match(/^(\d+) propuestas · (.+)$/);if(status)return status[1]+' dishes · '+(dict[status[2]]||status[2]);return text}
function translate(){const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);while(walker.nextNode()){const node=walker.currentNode;if(node.parentElement?.closest('script,style,svg,#review-text,.dish-title,#dish-title,.language-switch'))continue;const old=originals.get(node);let source=old&&node.data===old.rendered?old.source:node.data;const key=source.trim();const result=language==='en'?source.replace(key,english(key)):source;if(node.data!==result)node.data=result;originals.set(node,{source,rendered:result})}document.querySelectorAll('[aria-label],[placeholder]').forEach(el=>{const saved=attributes.get(el)||{};for(const name of ['aria-label','placeholder']){const value=el.getAttribute(name);if(!value)continue;const old=saved[name];const source=old&&value===old.rendered?old.source:value;const rendered=language==='en'?english(source):source;if(value!==rendered)el.setAttribute(name,rendered);saved[name]={source,rendered}}attributes.set(el,saved)});document.documentElement.lang=language;document.querySelectorAll('[data-language]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.language===language)))}
const reduced=matchMedia('(prefers-reduced-motion: reduce)'),seen=new WeakSet();const reveal=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-revealed');reveal.unobserve(entry.target)}})},{threshold:.06,rootMargin:'0px 0px 20px 0px'});function photos(){document.querySelectorAll('img').forEach(img=>{if(seen.has(img))return;seen.add(img);if(reduced.matches||img.closest('.brand,.reel-card')||img.classList.contains('dish-backdrop'))return;img.classList.add('photo-reveal');reveal.observe(img)})}const mutations=new MutationObserver(()=>{mutations.disconnect();translate();photos();watch()});function watch(){mutations.observe(document.body,{subtree:true,childList:true,characterData:true})}document.querySelectorAll('[data-language]').forEach(button=>button.addEventListener('click',()=>{language=button.dataset.language;try{localStorage.setItem('corte-language',language)}catch{}mutations.disconnect();translate();watch()}));translate();photos();watch();})();
(()=>{const track=document.querySelector('.ribbon-track'),group=track?.querySelector('.ribbon-group');if(!group)return;const reduce=matchMedia('(prefers-reduced-motion: reduce)');let animation,lastWidth=0;function start(){const width=group.getBoundingClientRect().width;if(!width||Math.abs(width-lastWidth)<1&&animation)return;const progress=animation?(Number(animation.currentTime)||0)/(lastWidth/36*1000):0;animation?.cancel();lastWidth=width;if(reduce.matches)return;const duration=width/36*1000;animation=track.animate([{transform:'translate3d(0,0,0)'},{transform:'translate3d(-'+width+'px,0,0)'}],{duration,iterations:Infinity,easing:'linear'});animation.currentTime=(progress%1)*duration}document.fonts.ready.then(start);new ResizeObserver(start).observe(group);reduce.addEventListener('change',()=>{animation?.cancel();animation=null;start()});document.addEventListener('visibilitychange',()=>{if(document.hidden)animation?.pause();else animation?.play()})})();
